activation_collect_sound.statement:
\<lbrakk>\<And>s.
            s \<in> S \<Longrightarrow>
            s \<in> cover (cfg_entry g) startcontext;
 \<And>u a v c s s'.
    \<lbrakk>(u, a, v) \<in> intra g; s \<in> cover u c;
     s' \<in> edge_step a s\<rbrakk>
    \<Longrightarrow> s' \<in> cover v c;
 \<And>u dst pars args p cont c c' s.
    \<lbrakk>(u, CallEdge dst pars args, FunctionEntry p, cont)
             \<in> calls g;
     s \<in> cover u c;
     R u c (call_info_of (CallEdge dst pars args) p) s
      (call_enter \<G> (CallEdge dst pars args) s) c'\<rbrakk>
    \<Longrightarrow> call_enter \<G> (CallEdge dst pars args) s
                      \<in> cover (FunctionEntry p) c';
 \<And>cl dst pars args p cont c1 c' p' s t es.
    \<lbrakk>(cl, CallEdge dst pars args, FunctionEntry p, cont)
             \<in> calls g;
     s \<in> cover cl c1; admits_call_context \<G> g R cl c1 p' s es c';
     t \<in> cover (FunctionResult p) c'\<rbrakk>
    \<Longrightarrow> combine_collect \<G> dst s t \<in> cover cont c1;
 call_context_total_on cover R \<G> g\<rbrakk>
\<Longrightarrow> \<A>\<^bsub>\<G>,R,startcontext,g,S\<^esub> v ctx
                  \<subseteq> cover v ctx

cstep_preserves_ltr_repr.statement:
\<lbrakk>wf_compile_input \<G> \<Pi> ps;
 \<G>,compile_prog \<Pi> ps \<turnstile> cf \<rightarrow>\<^sub>c cf';
 ltr_repr \<G> (compile_prog \<Pi> ps) S cf t\<rbrakk>
\<Longrightarrow> \<exists>t'.
                     ltr_repr \<G> (compile_prog \<Pi> ps) S cf' t'

intersect_shared_not_empty.statement:
\<lbrakk>semantic_intersection intersect; n \<in> \<gamma> a;
 n \<in> \<gamma> b\<rbrakk>
\<Longrightarrow> \<not> is_empty (intersect a b)

ltr_collect_semantic_postfix.statement:
\<lbrakk>S0.0 \<subseteq> B (cfg_entry g);
 \<And>u a w s s'.
    \<lbrakk>(u, a, w) \<in> intra g; s \<in> B u;
     s' \<in> edge_step a s\<rbrakk>
    \<Longrightarrow> s' \<in> B w;
 \<And>u dst pars args p cont s.
    \<lbrakk>(u, CallEdge dst pars args, FunctionEntry p, cont)
             \<in> calls g;
     s \<in> B u\<rbrakk>
    \<Longrightarrow> call_enter \<G> (CallEdge dst pars args) s
                      \<in> B (FunctionEntry p);
 \<And>cl dst pars args p cont s t.
    \<lbrakk>(cl, CallEdge dst pars args, FunctionEntry p, cont)
             \<in> calls g;
     s \<in> B cl; t \<in> B (FunctionResult p)\<rbrakk>
    \<Longrightarrow> combine_collect \<G> dst s t \<in> B cont\<rbrakk>
\<Longrightarrow> \<C>\<^bsub>\<G>,g,S0.0\<^esub> v \<subseteq> B v

pstep.Call.statement:
\<lbrakk>\<Pi> p = Some decl; length actuals = length (formals decl);
 distinct (formals decl);
 vals = map (\<lambda>e. \<lbrakk>e\<rbrakk>\<^sub>e s) actuals;
 callee = bind_formals (formals decl) vals (enter_state \<G> s)\<rbrakk>
\<Longrightarrow> \<G>,\<Pi> \<turnstile>
                  (com.Call dst p actuals, s, frs) \<rightarrow>\<^sub>p
                  (Seq (body decl) Restore, callee, Frame s dst # frs)

run_voblint_arithmetic_safe.statement:
\<lbrakk>config_terminates D rule ctx p;
 run_voblint D rule ctx p = Analysed res;
 s \<in> \<C>\<^bsub>declared_global
                      p,prog_cfg p,cinit_stores (declared_global p)\<^esub>
          v;
 \<forall>d\<in>set (res_diagnostics res).
    diagnostic_point d \<noteq> v\<rbrakk>
\<Longrightarrow> arithmetic_safe_at (prog_cfg p) v s

run_voblint_dead_check_unreached.statement:
\<lbrakk>config_terminates D rule ctx p;
 run_voblint D rule ctx p = Analysed res; chk \<in> set (res_checks res);
 check_verdict chk = Dead\<rbrakk>
\<Longrightarrow> \<C>\<^bsub>declared_global
                               p,prog_cfg
                                  p,cinit_stores (declared_global p)\<^esub>
                   (check_point chk) =
                  {}
